def merge_intervals(intervals):
    if not intervals:
        return []
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

import heapq


def toposort(nodes, edges):
    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    seen_edges = set()
    for src, dst in edges:
        if (src, dst) in seen_edges:
            continue
        seen_edges.add((src, dst))
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit πρέπει να είναι θετικός ακέραιος")
    if not items:
        return []
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("κάθε βάρος πρέπει να είναι θετικό και <= limit")
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    """Parse environment assignments from text into a dict."""
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Invalid environment assignment: {stripped!r}")
        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        if not key_pattern.match(key):
            raise ValueError(f"Invalid environment key: {key!r}")
        result[key] = value
    return result

def parse_sse(chunks):
    buffer = b''
    events = []
    current_data = []

    for chunk in chunks:
        buffer += chunk
        while True:
            nl = buffer.find(b'\n')
            if nl == -1:
                break
            line = buffer[:nl]
            buffer = buffer[nl + 1:]
            if line.endswith(b'\r'):
                line = line[:-1]
            text = line.decode('utf-8', errors='replace')

            if not text:
                # blank line dispatches the accumulated event
                if current_data:
                    data = '\n'.join(current_data)
                    if data == '[DONE]':
                        return events          # exclude [DONE] and everything after
                    events.append(data)
                    current_data = []
                # event without data -> ignored
            elif text.startswith(':'):
                pass                         # comment
            else:
                colon = text.find(':')
                if colon != -1 and text[:colon] == 'data':
                    value = text[colon + 1:]
                    if value.startswith(' '):
                        value = value[1:]    # remove at most one space
                    current_data.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")
    if not math.isfinite(base) or not math.isfinite(cap):
        raise ValueError("base and cap must be finite")

    # base == 0 => 0 * 2**attempt == 0; cap == 0 => result is 0 (min with 0)
    if base == 0 or cap == 0:
        return 0.0

    # base > 0, cap > 0.  value = base * 2**attempt.
    # value >= cap  iff  attempt >= log2(cap / base)
    # cap is finite, so this threshold is bounded (<= ~2098); when the
    # condition is FALSE the exponent is < that bound, so base * 2**attempt
    # cannot overflow.
    if attempt >= math.log2(cap / base):
        return float(cap)
    return min(float(cap), base * 2**attempt)

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError("queued reservation exceeds budget")

    used = sum(active)
    available_slots = slots - len(active)

    admitted = []
    remaining = []

    for i, q in enumerate(queued):
        if available_slots > 0 and used + q <= budget:
            admitted.append(q)
            used += q
            available_slots -= 1
        else:
            remaining = list(queued[i:])
            break

    return admitted, remaining
